package com.voicetxt.reader;
import android.app.*;import android.content.*;import android.os.*;import java.io.*;import java.util.*;
public class OriginalVoiceFilterTest extends VoiceWarmupTest {
 public void onStart(){Bundle result=new Bundle();SharedPreferences prefs=getTargetContext().getSharedPreferences("reading_settings",0);Map<String,?> saved=new HashMap<>(prefs.getAll());MainActivity reader=null;boolean success=false;try{check(!VoicePackages.get(getTargetContext()).list("sv").isEmpty(),"User Swedish model missing");prefs.edit().putString("readingLanguage","").commit();reader=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).putExtra("book_id","original_filter_qa").putExtra("book_name","原文音色筛选验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity a=reader;await(()->a.system!=null&&a.system.initialized,"System voice discovery not ready",30000);final VoicePicker.Item[] selected={null};ui(()->{a.chooseVoice();check(a.voicePicker.host.languages().contains("sv"),"Swedish language chip missing");check(a.voicePicker.languageScroll.getVisibility()==android.view.View.VISIBLE,"Original language bar hidden");a.voicePicker.host.language("sv");a.voicePicker.refresh();check(a.readingLanguage.isEmpty()&&a.voiceLanguage().equals("sv"),"Changing voice language changed translation mode");for(VoicePicker.Item item:a.voicePicker.host.items())if(VoicePackages.get(a).resolve(item.key,"sv")!=null){selected[0]=item;break;}check(selected[0]!=null,"Imported Swedish model not in original voice picker");a.voicePicker.host.select(selected[0]);check(a.previewKey.isEmpty()&&!a.playing,"Selection started playback");check(prefs.getString("voice_sv","").equals(selected[0].key),"Swedish voice preference not saved");a.voicePicker.host.preview(selected[0]);});await(()->a.offline instanceof PackageSpeaker&&((PackageSpeaker)a.offline).lastSynthesisMs>0&&!a.previewKey.isEmpty(),"Swedish preview failed",30000);ui(()->{a.voicePicker.host.preview(selected[0]);check(a.previewKey.isEmpty(),"Swedish preview pause failed");a.voicePicker.dismiss();a.readingLanguage="zh";a.ensureReadingVoice();a.chooseVoice();check(a.voicePicker.host.languages().isEmpty()&&a.voicePicker.languageScroll.getVisibility()==android.view.View.GONE,"Translation mode exposes other languages");for(VoicePicker.Item item:a.voicePicker.host.items())if(VoicePackages.isKey(item.key))check(VoicePackages.get(a).resolve(item.key,"zh")!=null,"Swedish model leaked into Chinese translation voices");a.voicePicker.dismiss();});result.putString("result","PASS: actual installed Swedish voice shown under Original/Swedish; selecting preserves original mode and saves Swedish preference without autoplay; Swedish preview/pause; Chinese translation mode remains filtered");success=true;}catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));}finally{if(reader!=null){final MainActivity a=reader;ui(()->{a.stop();a.finish();});}waitForIdleSync();restore(prefs,saved);getTargetContext().getSharedPreferences("reader_original_filter_qa",0).edit().clear().commit();new File(getTargetContext().getFilesDir(),"book_original_filter_qa.txt.position").delete();}finish(success?-1:0,result);}
}
